            D("Prohibited: External References", type="Restricted", description="No external streams except in PDF/A-3 attachments"),
            D("Prohibited: Audio/Video/3D", type="None in PDF/A-1; restricted PDF/A-2", description="Multimedia restricted"),
            D("Prohibited: Transparency", type="None in PDF/A-1", description="No alpha; allowed in PDF/A-2+"),
            D("Prohibited: LZW Compression", type="None allowed", description="ZIP/Flate only"),
