            D("/Title", type="text string", description="Document title"),
            D("/Author", type="text string", description="Author"),
            D("/Subject", type="text string", description="Subject"),
            D("/Keywords", type="text string", description="Keywords (comma or space separated)"),
            D("/Creator", type="text string", description="Application that created original (e.g., 'Microsoft Word')"),
            D("/Producer", type="text string", description="Library/app that converted to PDF (e.g., 'Adobe PDF Library 15.0')"),
            D("/CreationDate", type="date string D:YYYYMMDDHHmmSSOHH'mm'", description="Original creation date"),
            D("/ModDate", type="date string", description="Last modification date"),
