            D("/Type /Filespec", type="Required", group="Filespec", description="Mandatory type marker"),
            D("/F (file name)", type="Text string", group="Filespec", description="Plain ASCII file name"),
            D("/UF (Unicode file name)", type="Text string", group="Filespec", description="Unicode file name (preferred)"),
            D("/DOS / /Mac / /Unix", type="byte strings", group="Filespec", description="Legacy platform-specific names"),
            D("/EF (embedded file dictionary)", type="Dictionary", group="Filespec", description="Maps platforms to file streams"),
            D("/EF /F", type="Stream", group="Filespec", description="Embedded file stream (preferred — platform-independent)"),
            D("/EF /UF", type="Stream", group="Filespec", description="Unicode-named embedded stream"),
            D("/Desc", type="Text string", group="Filespec", description="Description shown in attachment list"),
            D("/CI (collection item dictionary)", type="Dictionary", group="Filespec", description="PDF Portfolio metadata for this entry"),
            D("/AFRelationship", type="Name", group="Filespec", description="Source, Data, Alternative, Supplement, EncryptedPayload, FormData, Schema, Unspecified — required PDF/A-3"),
            D("/Thumb", type="Stream", group="Filespec", description="Thumbnail"),
            D("Stream /Type /EmbeddedFile", type="Required", group="Stream", description="Stream type marker"),
            D("Stream /Subtype", type="Name (MIME)", group="Stream", description="MIME type encoded as name (e.g., /text#2Fxml)"),
            D("Stream /Params /Size", type="Integer", group="Stream Params", description="File size in bytes"),
