            D("/SubFilter", type="Name", group="Sig dict", description="Encoding format — adbe.x509.rsa_sha1 (legacy), adbe.pkcs7.detached, adbe.pkcs7.sha1, ETSI.CAdES.detached, ETSI.RFC3161 (timestamp)"),
            D("/Contents", type="Hex string (PKCS#7)", group="Sig dict", description="The signature itself — DER-encoded PKCS#7/CMS containing certs, signed attrs, signature value"),
            D("/ByteRange", type="Array of 4 integers", group="Sig dict", description="Byte ranges hashed (gap covers /Contents)"),
            D("/Cert", type="Byte string or array", group="Sig dict", description="Signing certificate(s) when SubFilter is x509.rsa_sha1"),
