            D("/V", type="Integer", group="Sig dict", description="Sub-revision"),
            D("/Prop_Build", type="Dictionary", group="Sig dict", description="App build properties (App, PubSec, Filter)"),
            D("/Prop_AuthTime", type="Integer", group="Sig dict", description="Seconds since auth"),
            D("/Prop_AuthType", type="Name", group="Sig dict", description="PIN / Password / Fingerprint"),
            D("Signature Type — Approval", type="Form field signature", description="One of multiple possible signatures, doesn't lock"),
            D("Signature Type — Certification (MDP)", type="DocMDP transform", description="Single doc-locking signature; Permissions: 1=no changes, 2=form fill+annotate allowed, 3=form fill+annotate+modifications allowed"),
            D("Signature Type — UR (Usage Rights)", type="UR3 transform", description="Reader-enabled rights"),
            D("Signature Type — FieldMDP", type="FieldMDP transform", description="Locks specific form fields"),
